solution_sql:
SELECT p.first_name, p.last_name, pn.province_name
FROM patients p
JOIN province_names pn ON pn.province_id = p.province_id;

SELECT p.patient_id, p.first_name, p.last_name
FROM patients p JOIN admissions a ON a.patient_id = p.patient_id
WHERE a.diagnosis = 'Dementia';

SELECT
  (SELECT COUNT(*) FROM patients WHERE gender = 'M') AS male_count,
  (SELECT COUNT(*) FROM patients WHERE gender = 'F') AS female_count;

SELECT first_name, last_name, allergies FROM patients
WHERE allergies IN ('Penicillin', 'Morphine')
ORDER BY allergies, first_name, last_name;

SELECT first_name, last_name, 'Patient' AS role FROM patients
UNION ALL
SELECT first_name, last_name, 'Doctor' AS role FROM doctors;

SELECT allergies, COUNT(*) AS total_diagnosis FROM patients
WHERE allergies IS NOT NULL AND allergies <> 'NKA'
GROUP BY allergies ORDER BY total_diagnosis DESC;

SELECT first_name, last_name, birth_date FROM patients
WHERE birth_date BETWEEN '1970-01-01' AND '1979-12-31'
ORDER BY birth_date ASC;

SELECT CAST(strftime('%d', admission_date) AS INTEGER) AS day_number,
       COUNT(*) AS number_of_admissions
FROM admissions GROUP BY day_number ORDER BY number_of_admissions DESC;

SELECT d.first_name, d.last_name, COUNT(*) AS admissions_total
FROM admissions a JOIN doctors d ON d.doctor_id = a.attending_doctor_id
GROUP BY d.doctor_id, d.first_name, d.last_name;

SELECT pn.province_name, COUNT(*) AS patient_count
FROM patients p JOIN province_names pn ON pn.province_id = p.province_id
GROUP BY pn.province_name ORDER BY patient_count DESC;

SELECT MAX(daily) AS max_visits, MIN(daily) AS min_visits,
       ROUND(AVG(daily), 2) AS average_visits
FROM (SELECT COUNT(*) AS daily FROM admissions GROUP BY admission_date);

SELECT CASE WHEN patient_id % 2 = 0 THEN 'Yes' ELSE 'No' END AS has_insurance,
       SUM(CASE WHEN patient_id % 2 = 0 THEN 10 ELSE 50 END) AS cost_after_insurance
FROM admissions GROUP BY has_insurance;

SELECT ROUND(100.0 * SUM(CASE WHEN gender = 'M' THEN 1 ELSE 0 END) / COUNT(*), 2)
       || '%' AS percent_of_male_patients
FROM patients;
